import {setContextSwitching} from '@erpx/feature-work_projection/lib/context-switch';
const salesSeed='a'.repeat(64);
function salesSetup():SalesPostingSetupView{return {companyId:'company',available:true,contextKey:salesSeed,unavailableReason:null,canCreateChart:true,canCreateAccount:true,canCreatePeriod:true,canConfirmRate:false,canPrepareDefaults:true,charts:[{id:'chart',name:'Actual service chart',baseCurrency:'THB'}],accounts:[{id:'ar',chartId:'chart',code:'110',name:'Actual receivables',category:'asset',currency:'THB',controlKind:'receivable'},{id:'revenue',chartId:'chart',code:'410',name:'Actual service revenue',category:'revenue',currency:'THB',controlKind:'none'},{id:'vat',chartId:'chart',code:'210',name:'Actual output VAT',category:'liability',currency:'THB',controlKind:'none'}],periods:[{id:'period',name:'Actual open period',startDate:'2026-10-01',endDate:'2026-10-31',state:'open',version:0}],rates:[{id:'rate',currency:'THB',effectiveDate:'2026-10-01',currencyPerUsd:'35',confirmedAt:10}],defaults:[{id:'defaults',chartId:'chart',currency:'THB',receivableAccountId:'ar',revenueAccountId:'revenue',taxAccountId:'vat',status:'draft',version:1,reason:'Original independently reviewed source',reviewReason:null,canReview:false,canApprove:false,canReject:false,usable:false}]};}
const salesRequests:SalesPostingRequest[]=[
 {kind:'charts',body:{expectedVersion:0,contextKey:salesSeed,input:{name:'Actual service chart',baseCurrency:'THB',accountingBasis:'IFRS'}}},
 {kind:'accounts',body:{expectedVersion:0,contextKey:salesSeed,input:{chartId:'chart',code:'110',name:'Actual receivables',category:'asset',currency:'THB',isControl:true,controlKind:'receivable'}}},
 {kind:'periods',body:{expectedVersion:0,contextKey:salesSeed,input:{name:'Actual open period',startDate:'2026-10-01',endDate:'2026-10-31'}}},
 {kind:'rates',body:{expectedVersion:0,contextKey:salesSeed,input:{currency:'THB',effectiveDate:'2026-10-01',currencyPerUsd:'35',note:'Original confirmed rate'}}},
 {kind:'defaults',body:{expectedVersion:0,contextKey:salesSeed,input:{chartId:'chart',currency:'THB',receivableAccountId:'ar',revenueAccountId:'revenue',taxAccountId:'vat',reason:'Original reviewed service posting'}}},
 {kind:'decision',id:'defaults',body:{contextKey:salesSeed,input:{expectedVersion:1,action:'approve',reason:'Independent person checked actual references'}}}
];
function salesReceipt(request:SalesPostingRequest,key='original-key'):Record<string,unknown>{
 if(request.kind==='charts')return {id:'chart',companyId:'company',...request.body.input,version:1};
 if(request.kind==='accounts')return {id:'ar',companyId:'company',...request.body.input,version:1};
 if(request.kind==='periods')return {id:'period',companyId:'company',...request.body.input,state:'open',version:0};
 if(request.kind==='rates')return {id:'rate',currency:'THB',effectiveDate:'2026-10-01',currencyPerUsd:'35',confirmedAt:10};
 if(request.kind==='defaults')return {id:`sales-defaults-${key}`,status:'draft',version:1};
 return {id:request.id,status:request.body.input.action==='approve'?'approved':'rejected',version:request.body.input.expectedVersion+1};
}
function salesViewAfter(request:SalesPostingRequest,key='original-key'){
 const view=salesSetup();if(request.kind==='defaults')view.defaults=[{...view.defaults[0],id:`sales-defaults-${key}`}];if(request.kind==='decision')view.defaults=[{...view.defaults[0],status:request.body.input.action==='approve'?'approved':'rejected',version:2,usable:request.body.input.action==='approve'}];return view;
}
function salesBrowser(){
 const node={isConnected:true,dataset:{workUser:'seller',workRevision:'7',workCompany:'company',workAssignment:'sales-role',workStale:'false'}},browser=Object.assign(new EventTarget(),{location:{origin:'https://sales-dev-erpx.jesadakorn.com'}}),events:string[]=[];
 for(const type of ['erpx:record-command-saved','erpx:work-changed','erpx:finance-command-acknowledged'])browser.addEventListener(type,()=>events.push(type));
 vi.stubGlobal('window',browser);vi.stubGlobal('document',{querySelector:(selector:string)=>selector==='[data-work-revision]'&&node.isConnected?node:null,activeElement:{closest:()=>null},documentElement:{dataset:{}}});return {node,events};
}
function salesNetwork(request:SalesPostingRequest){let key='';return vi.fn<(url:RequestInfo|URL,init?:RequestInit)=>Promise<Response>>(async(_url,init)=>{if(init?.method==='POST'){key=new Headers(init.headers).get('Idempotency-Key')??'';return Response.json({data:salesReceipt(request,key)});}return Response.json({data:salesViewAfter(request,key)});});}
afterEach(()=>{if(typeof document!=='undefined')setContextSwitching(false);vi.unstubAllGlobals();});
