 const denied={...salesSetup(),available:false,contextKey:null,unavailableReason:'purchase-required' as const,canCreateChart:false,canCreateAccount:false,canCreatePeriod:false,canConfirmRate:false,canPrepareDefaults:false,charts:[],accounts:[],periods:[],rates:[],defaults:[]};const unavailable=renderToStaticMarkup(createElement(SalesPostingSetup,{base:'/holdings/acme',initial:denied}));expect(unavailable).toContain('Sales posting purchase is required');expect(unavailable).not.toContain('Actual receivables');expect(unavailable).not.toContain('Create a chart');
