test.each(['revision','stale','removed','generation'] as const)('actual workFetch original JSON delays retain the key across late %s and exact context recovery',async changed=>{
 const browser=salesBrowser(),request=salesRequests[4],source={base:'/holdings/acme',companyId:'company',contextKey:salesSeed};let release!:()=>void,started!:()=>void,first=true,key='';const ready=new Promise<void>(resolve=>{started=resolve;}),paused=new Promise<void>(resolve=>{release=resolve;});class OriginalJSON extends Response{override async json(){started();await paused;return super.json();}}
 const network=vi.fn<(url:RequestInfo|URL,init?:RequestInit)=>Promise<Response>>(async(_url,init)=>{if(init?.method==='POST'){key=new Headers(init.headers).get('Idempotency-Key')??'';const body={data:salesReceipt(request,key)};if(first){first=false;return new OriginalJSON(JSON.stringify(body),{headers:{'Content-Type':'application/json'}});}return Response.json(body);}return Response.json({data:salesViewAfter(request,key)});});vi.stubGlobal('fetch',network);const commands=createSalesPostingCommands(()=>source);
 try{const pending=commands.submit(request);await ready;expect(browser.events).toEqual([]);if(changed==='revision')browser.node.dataset.workRevision='8';else if(changed==='stale')browser.node.dataset.workStale='true';else if(changed==='removed')browser.node.isConnected=false;else setContextSwitching(true);release();await expect(pending).rejects.toMatchObject({code:'WORK_CONTEXT_CHANGED'});expect(commands.pending()).toBe(true);expect(browser.events).toEqual([]);
 browser.node.dataset.workRevision='7';browser.node.dataset.workStale='false';browser.node.isConnected=true;setContextSwitching(false);const retry=await commands.retry();expect(retry.acknowledge()).toBe(true);const posts=network.mock.calls.filter(([,init])=>init?.method==='POST');expect(posts).toHaveLength(2);expect(new Set(posts.map(([,init])=>new Headers(init?.headers).get('Idempotency-Key'))).size).toBe(1);expect(new Set(posts.map(([,init])=>init?.body)).size).toBe(1);expect(browser.events).toEqual(['erpx:work-changed']);}finally{release();}
});
test('a Company change during fresh setup decoding withholds acknowledgement and preserves the original source/body/key',async()=>{
 const browser=salesBrowser(),request=salesRequests[0],source={base:'/holdings/acme',companyId:'company',contextKey:salesSeed};let release!:()=>void,started!:()=>void,delayed=false;const ready=new Promise<void>(resolve=>{started=resolve;}),paused=new Promise<void>(resolve=>{release=resolve;});class DelayedStatus extends Response{override async json(){started();await paused;return super.json();}}
 const network=vi.fn<(url:RequestInfo|URL,init?:RequestInit)=>Promise<Response>>(async(_url,init)=>init?.method==='POST'?Response.json({data:salesReceipt(request)}):!delayed?(delayed=true,new DelayedStatus(JSON.stringify({data:salesSetup()}))):Response.json({data:salesSetup()}));vi.stubGlobal('fetch',network);const commands=createSalesPostingCommands(()=>source);
 try{const pending=commands.submit(request);await ready;source.companyId='different';release();await expect(pending).rejects.toMatchObject({code:'WORK_CONTEXT_CHANGED'});expect(commands.applied()).toBe(true);expect(commands.pending()).toBe(true);expect(browser.events).toEqual([]);await expect(commands.retry()).rejects.toThrow('original Company');source.companyId='company';const retry=await commands.retry();expect(retry.acknowledge()).toBe(true);const posts=network.mock.calls.filter(([,init])=>init?.method==='POST');expect(posts[1][1]?.body).toBe(posts[0][1]?.body);expect(new Headers(posts[1][1]?.headers).get('Idempotency-Key')).toBe(new Headers(posts[0][1]?.headers).get('Idempotency-Key'));}finally{release();}
});
